package com.aicharacter.v3;import java.util.*;
public final class TravelDiagnostics{private TravelDiagnostics(){}private static String f(double x){return Double.isFinite(x)?String.format(Locale.US,"%.2f",x):"unset";}
 public static String travel(WorldState s){TravelState t=s.girlTravel;return"TRAVEL TRACE V3\nentity="+t.actor+" mode="+t.travelMode+" origin="+t.originArea+" destination="+t.destinationArea+"\nroute="+t.route+" index="+t.routeIndex+"\nsegment="+t.currentSegment()+" startX="+f(t.segmentStartX)+" endX="+f(t.segmentEndX)+" progress="+f(t.progress)+"\ncurrentX="+f(s.haruX)+" previousX="+f(t.previousX)+" delta="+f(t.lastDelta)+" speed="+f(t.lastSpeed)+"\ntarget="+t.targetType+":"+t.targetId+" interactionRange="+f(t.interactionRange)+"\nattachment="+s.catState.attachedToEntity+" invalidation="+t.lastInvalidation+" replan="+t.lastReplan+" interruption="+t.interruption;}
 public static String perception(WorldState s){return s.lastPerceptionTrace.isEmpty()?"No bounded travel perception event in this runtime.":s.lastPerceptionTrace;}
 public static String route(WorldState s){TravelState t=s.girlTravel;StringBuilder b=new StringBuilder("ROUTE TRACE\n");for(int i=0;i<t.route.size()-1;i++){WorldConnection c=WorldPathPlanner.connection(s.world,t.route.get(i),t.route.get(i+1));b.append(c==null?"invalid":c.id+" cost="+String.format(Locale.US,"%.1f",WorldPathPlanner.cost(s,c,"girl"))+" anchors="+(int)c.exitX+"->"+(int)c.entryX+" blocked="+s.routeRuntime.blocked(c.id)).append('\n');}return b.toString();}}
